import React from "react";
import { action } from "@storybook/addon-actions";
import FormControl from "../Form/FormControl";
import TimePicker from "./TimePicker";
import type { Meta, StoryObj } from "@storybook/react";
import { ColorModeProvider } from "../../lib/styling";
import Stack from "../Stack";
import withDarkMode from "../../lib/utils/storybookDecorators";

const meta: Meta<typeof TimePicker> = {
  id: "Components/TimePicker",
  title: "Components/Date & Time Picker/Time Picker",
  component: TimePicker,
};

export default meta;
type Story = StoryObj<typeof TimePicker>;

export const Basic: Story = {
  tags: ["visual-test"],
  render: (args) => (
    <div className="w-112">
      <TimePicker {...args} onChange={action("onChange")} />
    </div>
  ),
};

export const Period: Story = {
  render: (args) => (
    <div className="w-208">
      <TimePicker {...args} use12Hours onChange={action("onChange")} />
    </div>
  ),
};

export const Dark: Story = {
  tags: ["visual-test"],
  decorators: [withDarkMode],
  render: () => (
    <Stack spacing="1-x">
      <div className="w-112">
        <TimePicker onChange={action("onChange")} />
      </div>
      <div className="w-208">
        <TimePicker onChange={action("onChange")} use12Hours />
      </div>
    </Stack>
  ),
};

export const Clear: Story = {
  parameters: { docs: { source: { type: "code" }}},
  render: () => {
    const [value, setValue] = React.useState("11:21");
    return (
      <div className="w-112">
        <TimePicker
          showClearButton
          value={value}
          onChange={(val: any) => setValue(val)}
        />
      </div>
    );
  },
};

export const Controlled: Story = {
  parameters: { docs: { source: { type: "code" }}},
  render: () => {
    const [value, setValue] = React.useState("10:10");
    return (
      <div className="w-112">
        <TimePicker onChange={(val) => setValue(val)} value={value} />
      </div>
    );
  },
};

export const Validation: Story = {
  parameters: { docs: { source: { type: "code" }}},
  render: () => {
    const [isValid, setValid] = React.useState(true);
    return (
      <FormControl
        className="w-112"
        helpText="e.g. 18:45"
        errorText="Invalid time (hh:mm)"
        error={!isValid}
        label="Set time"
        required
      >
        <TimePicker onValidation={(valid: boolean) => setValid(valid)} />
      </FormControl>
    );
  },
};
